 "content": "def transform(grid):
    """Recolor maximal monochrome rectangles of at least 5x5 to color 4."""
    h, w = len(grid), len(grid[0])
    colors = set(value for row in grid for value in row)
    rectangles = set()

    # Intersect equal-color columns over each possible vertical span. Each
    # contiguous run in the intersection is horizontally maximal.
    for color in colors:
        for top in range(h):
            valid = [True] * w
            for bottom in range(top, h):
                row = grid[bottom]
                valid = [valid[c] and row[c] == color for c in range(w)]
                height = bottom - top + 1
                if height < 5:
                    continue
                c = 0
                while c < w:
                    if not valid[c]:
                        c += 1
                        continue
                    left = c
                    while c < w and valid[c]:
                        c += 1
                    right = c - 1
                    if right - left + 1 < 5:
                        continue
                    # Reject any rectangle extendable vertically while
                    # preserving the entire monochrome block.
                    can_extend_up = top > 0 and all(
                        grid[top - 1][x] == color for x in range(left, right + 1)
                    )
                    can_extend_down = bottom + 1 < h and all(
                        grid[bottom + 1][x] == color for x in range(left, right + 1)
                    )
                    if not can_extend_up and not can_extend_down:
                        rectangles.add((top, left, bottom, right))

    output = [row[:] for row in grid]
    for top, left, bottom, right in rectangles:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                output[r][c] = 4
    return output
